pub fn ranges(xs: List[Int]) -> Str {
  let ys = xs.unique().sort()
  let n = ys.len()
  var parts: List[Str] = []
  var i = 0
  while i < n {
    let lo = ys.get_or(i, 0)
    var j = i
    while j + 1 < n and ys.get_or(j + 1, 0) == ys.get_or(j, 0) + 1 {
      j = j + 1
    }
    let hi = ys.get_or(j, 0)
    if j - i >= 2 {
      parts = parts.push("{lo}-{hi}")
    } else {
      parts = parts.push(lo.to_str())
      if j > i {
        parts = parts.push(hi.to_str())
      }
    }
    i = j + 1
  }
  return parts.join(",")
}
